auto ctor=JSValue::builtinConstructor(method0,{module},"CubeRenderTarget",0);ctor.setFunctionSourceText("class CubeRenderTarget extends RenderTarget {\r\n\r\n\t/**\r\n\t * Constructs a new cube render target.\r\n\t *\r\n\t * @param {number} [size=1] - The size of the render target.\r\n\t * @param {RenderTarget~Options} [options] - The configuration object.\r\n\t */\r\n\tconstructor( size = 1, options = {} ) {\r\n\r\n\t\tsuper( size, size, options );\r\n\r\n\t\t/**\r\n\t\t * This flag can be used for type testing.\r\n\t\t *\r\n\t\t * @type {boolean}\r\n\t\t * @readonly\r\n\t\t * @default true\r\n\t\t */\r\n\t\tthis.isCubeRenderTarget = true;\r\n\r\n\t\tconst image = { width: size, height: size, depth: 1 };\r\n\t\tconst images = [ image, image, image, image, image, image ];\r\n\r\n\t\t/**\r\n\t\t * Overwritten with a different texture type.\r\n\t\t *\r\n\t\t * @type {DataArrayTexture}\r\n\t\t */\r\n\t\tthis.texture = new CubeTexture( images );\r\n\t\tthis._setTextureOptions( options );\r\n\r\n\t\t// By convention -- likely based on the RenderMan spec from the 1990's -- cube maps are specified by WebGL (and three.js)\r\n\t\t// in a coordinate system in which positive-x is to the right when looking up the positive-z axis -- in other words,\r\n\t\t// in a left-handed coordinate system. By continuing this convention, preexisting cube maps continued to render correctly.\r\n\r\n\t\t// three.js uses a right-handed coordinate system. So environment maps used in three.js appear to have px and nx swapped\r\n\t\t// and the flag isRenderTargetTexture controls this conversion. The flip is not required when using WebGLCubeRenderTarget.texture\r\n\t\t// as a cube texture (this is detected when isRenderTargetTexture is set to true for cube textures).\r\n\r\n\t\tthis.texture.isRenderTargetTexture = true;\r\n\r\n\t}\r\n\r\n\t/**\r\n\t * Converts the given equirectangular texture to a cube map.\r\n\t *\r\n\t * @param {Renderer} renderer - The renderer.\r\n\t * @param {Texture} texture - The equirectangular texture.\r\n\t * @return {CubeRenderTarget} A reference to this cube render target.\r\n\t */\r\n\tfromEquirectangularTexture( renderer, texture ) {\r\n\r\n\t\tconst currentMinFilter = texture.minFilter;\r\n\t\tconst currentGenerateMipmaps = texture.generateMipmaps;\r\n\r\n\t\ttexture.generateMipmaps = true;\r\n\r\n\t\tthis.texture.type = texture.type;\r\n\t\tthis.texture.colorSpace = texture.colorSpace;\r\n\r\n\t\tthis.texture.generateMipmaps = texture.generateMipmaps;\r\n\t\tthis.texture.minFilter = texture.minFilter;\r\n\t\tthis.texture.magFilter = texture.magFilter;\r\n\r\n\t\tconst geometry = new BoxGeometry( 5, 5, 5 );\r\n\r\n\t\tconst uvNode = equirectUV( positionWorldDirection );\r\n\r\n\t\tconst material = new NodeMaterial();\r\n\t\tmaterial.colorNode = TSL_Texture( texture, uvNode, 0 );\r\n\t\tmaterial.side = BackSide;\r\n\t\tmaterial.blending = NoBlending;\r\n\r\n\t\tconst mesh = new Mesh( geometry, material );\r\n\r\n\t\tconst scene = new Scene();\r\n\t\tscene.add( mesh );\r\n\r\n\t\t// Avoid blurred poles\r\n\t\tif ( texture.minFilter === LinearMipmapLinearFilter ) texture.minFilter = LinearFilter;\r\n\r\n\t\tconst camera = new CubeCamera( 1, 10, this );\r\n\r\n\t\tconst currentMRT = renderer.getMRT();\r\n\t\trenderer.setMRT( null );\r\n\r\n\t\tcamera.update( renderer, scene );\r\n\r\n\t\trenderer.setMRT( currentMRT );\r\n\r\n\t\ttexture.minFilter = currentMinFilter;\r\n\t\ttexture.generateMipmaps = currentGenerateMipmaps;\r\n\r\n\t\tmesh.geometry.dispose();\r\n\t\tmesh.material.dispose();\r\n\r\n\t\treturn this;\r\n\r\n\t}\r\n\r\n\t/**\r\n\t * Clears this cube render target.\r\n\t *\r\n\t * @param {Renderer} renderer - The renderer.\r\n\t * @param {boolean} [color=true] - Whether the color buffer should be cleared or not.\r\n\t * @param {boolean} [depth=true] - Whether the depth buffer should be cleared or not.\r\n\t * @param {boolean} [stencil=true] - Whether the stencil buffer should be cleared or not.\r\n\t */\r\n\tclear( renderer, color = true, depth = true, stencil = true ) {\r\n\r\n\t\tconst currentRenderTarget = renderer.getRenderTarget();\r\n\r\n\t\tfor ( let i = 0; i < 6; i ++ ) {\r\n\r\n\t\t\trenderer.setRenderTarget( this, i );\r\n\r\n\t\t\trenderer.clear( color, depth, stencil );\r\n\r\n\t\t}\r\n\r\n\t\trenderer.setRenderTarget( currentRenderTarget );\r\n\r\n\t}\r\n\r\n}");auto prototype=ctor.get("prototype");own(module,"CubeRenderTarget",ctor);own(module,"_home",prototype);
